focus-timer.script:
// An open page ends a countdown that's over and logs it.
setInterval(() => {
  const { minutes, started } = App.data;
  if (!started || Date.parse(started) + minutes * 6e4 > Date.now()) return;
  const note = document.querySelector("[data-part=entry-form] [data-ref=text]");
  const text = note.value.trim() || `${minutes}-minute session`;
  note.value = "";
  App.patch([{ op: "test", path: "/started", value: started }, { op: "replace", path: "/started", value: null },
    { op: "add", path: "/entries/-", value: { text, at: new Date(Date.parse(started) + minutes * 6e4).toISOString() } }], { ev: "done", text });
}, 1000);
